pub const TensorShape = struct {
    dims: []usize,
    allocator: mem.Allocator,

    pub fn init(allocator: mem.Allocator, dims: []const usize) !TensorShape {
        var self = TensorShape{
            .dims = try allocator.dupe(usize, dims),
            .allocator = allocator,
        };
        return self;
    }

    pub fn deinit(self: *TensorShape) void {
        self.allocator.free(self.dims);
    }

    pub fn total_elements(self: *const TensorShape) usize {
        var total: usize = 1;
        for (self.dims) |dim| {
            total *= dim;
        }
        return total;
    }

    pub fn broadcast(self: *const TensorShape, other: *const TensorShape) !TensorShape {
        if (self.dims.len != other.dims.len) return error.ShapeMismatch;
        var new_dims = try self.allocator.alloc(usize, self.dims.len);
        errdefer self.allocator.free(new_dims);
        for (self.dims, other.dims, 0..) |d1, d2, i| {
            if (d1 == d2) {
                new_dims[i] = d1;
            } else if (d1 == 1) {
                new_dims[i] = d2;
            } else if (d2 == 1) {
                new_dims[i] = d1;
            } else {
                self.allocator.free(new_dims);
                return error.BroadcastError;
            }
        }
        return TensorShape.init(self.allocator, new_dims);
    }

    pub fn dupe(self: *const TensorShape, allocator: Allocator) !TensorShape {
        return try TensorShape.init(allocator, self.dims);
    }
};

pub const TensorData = union(enum) {
    f32: []f32,
    f64: []f64,
    i32: []i32,
    u32: []u32,
    i64: []i64,
    u64: []u64,

    pub fn deinit(self: *TensorData, allocator: mem.Allocator) void {
        switch (self.*) {
            .f32 => |*data| allocator.free(data),
            .f64 => |*data| allocator.free(data),
            .i32 => |*data| allocator.free(data),
            .u32 => |*data| allocator.free(data),
            .i64 => |*data| allocator.free(data),
            .u64 => |*data| allocator.free(data),
        }
    }

    pub fn slice(self: TensorData, start: usize, end: usize) TensorData {
        return switch (self) {
            .f32 => |data| .{ .f32 = data[start..end] },
            .f64 => |data| .{ .f64 = data[start..end] },
            .i32 => |data| .{ .i32 = data[start..end] },
            .u32 => |data| .{ .u32 = data[start..end] },
            .i64 => |data| .{ .i64 = data[start..end] },
            .u64 => |data| .{ .u64 = data[start..end] },
        };
    }

    pub fn get_scalar(self: TensorData, index: usize) ?f64 {
        return switch (self) {
            .f32 => |data| if (index < data.len) @as(f64, data[index]) else null,
            .f64 => |data| if (index < data.len) data[index] else null,
            .i32 => |data| if (index < data.len) @as(f64, @floatFromInt(data[index])) else null,
            .u32 => |data| if (index < data.len) @as(f64, @floatFromInt(data[index])) else null,
            .i64 => |data| if (index < data.len) @as(f64, @floatFromInt(data[index])) else null,
            .u64 => |data| if (index < data.len) @as(f64, @floatFromInt(data[index])) else null,
        };
    }

    pub fn set_scalar(self: TensorData, index: usize, value: f64) !void {
        switch (self) {
            .f32 => |data| if (index < data.len) data[index] = @floatCast(value) else return error.IndexOutOfBounds,
            .f64 => |data| if (index < data.len) data[index] = value else return error.IndexOutOfBounds,
            .i32 => |data| if (index < data.len) data[index] = @intFromFloat(value) else return error.IndexOutOfBounds,
            .u32 => |data| if (index < data.len) data[index] = @intFromFloat(value) else return error.IndexOutOfBounds,
            .i64 => |data| if (index < data.len) data[index] = @intFromFloat(value) else return error.IndexOutOfBounds,
            .u64 => |data| if (index < data.len) data[index] = @intFromFloat(value) else return error.IndexOutOfBounds,
        }
    }

    pub fn to_f64_slice(self: TensorData) []f64 {
        return switch (self) {
            .f32 => |data| blk: {
                var slice = allocator.alloc(f64, data.len) catch unreachable;
                for (data, 0..) |val, i| {
                    slice[i] = @floatFromInt(val);
                }
                break :blk slice;
            },
            .f64 => |data| data,
            .i32 => |data| blk: {
                var slice = allocator.alloc(f64, data.len) catch unreachable;
                for (data, 0..) |val, i| {
                    slice[i] = @floatFromInt(val);
                }
                break :blk slice;
            },
            .u32 => |data| blk: {
                var slice = allocator.alloc(f64, data.len) catch unreachable;
                for (data, 0..) |val, i| {
                    slice[i] = @floatFromInt(val);
                }
                break :blk slice;
            },
            .i64 => |data| blk: {
                var slice = allocator.alloc(f64, data.len) catch unreachable;
                for (data, 0..) |val, i| {
                    slice[i] = @floatFromInt(val);
                }
                break :blk slice;
            },
            .u64 => |data| blk: {
                var slice = allocator.alloc(f64, data.len) catch unreachable;
                for (data, 0..) |val, i| {
                    slice[i] = @floatFromInt(val);
                }
                break :blk slice;
            },
        };
    }
};

pub const DType = enum {
    f32,
    f64,
    i32,
    u32,
    i64,
    u64,

    pub fn size(self: DType) usize {
        return switch (self) {
            .f32, .i32, .u32 => 4,
            .f64, .i64, .u64 => 8,
        };
    }

    pub fn zero(self: DType) f64 {
        return switch (self) {
            .f32, .f64 => 0.0,
            .i32 => 0,
            .u32 => 0,
            .i64 => 0,
            .u64 => 0,
        };
    }
};

pub const Tensor = struct {
    shape: TensorShape,
    data: TensorData,
    allocator: mem.Allocator,
    dtype: DType,
    strides: []usize,
    offset: usize = 0,

    pub fn init(allocator: mem.Allocator, shape: TensorShape, dtype: DType) !Tensor {
        const total = shape.total_elements();
        var data: TensorData = switch (dtype) {
            .f32 => .{ .f32 = try allocator.alloc(f32, total) },
            .f64 => .{ .f64 = try allocator.alloc(f64, total) },
            .i32 => .{ .i32 = try allocator.alloc(i32, total) },
            .u32 => .{ .u32 = try allocator.alloc(u32, total) },
            .i64 => .{ .i64 = try allocator.alloc(i64, total) },
            .u64 => .{ .u64 = try allocator.alloc(u64, total) },
        };
        var strides = try allocator.alloc(usize, shape.dims.len);
        errdefer allocator.free(strides);
        var stride: usize = 1;
        for (shape.dims.len - 1..0) |i| {
            strides[i] = stride;
            stride *= shape.dims[i + 1];
        }
        if (shape.dims.len > 0) {
            strides[0] = stride;
        }
        return Tensor{
            .shape = shape,
            .data = data,
            .allocator = allocator,
            .dtype = dtype,
            .strides = strides,
        };
    }

    pub fn deinit(self: *Tensor) void {
        self.data.deinit(self.allocator);
        self.allocator.free(self.strides);
        self.shape.deinit();
    }

    pub fn zeros_like(self: *const Tensor, allocator: Allocator) !Tensor {
        var new_shape = try self.shape.dupe(allocator);
        var new_tensor = try Tensor.init(allocator, new_shape, self.dtype);
        const total = new_tensor.shape.total_elements();
        switch (new_tensor.dtype) {
            .f32 => @memset(new_tensor.data.f32, 0),
            .f64 => @memset(new_tensor.data.f64, 0),
            .i32 => @memset(new_tensor.data.i32, 0),
            .u32 => @memset(new_tensor.data.u32, 0),
            .i64 => @memset(new_tensor.data.i64, 0),
            .u64 => @memset(new_tensor.data.u64, 0),
        }
        return new_tensor;
    }

    pub fn ones_like(self: *const Tensor, allocator: Allocator) !Tensor {
        var new_tensor = try self.zeros_like(allocator);
        const total = new_tensor.shape.total_elements();
        switch (new_tensor.dtype) {
            .f32 => for (new_tensor.data.f32[0..total]) |*val| val.* = 1.0,
            .f64 => for (new_tensor.data.f64[0..total]) |*val| val.* = 1.0,
            .i32 => for (new_tensor.data.i32[0..total]) |*val| val.* = 1,
            .u32 => for (new_tensor.data.u32[0..total]) |*val| val.* = 1,
            .i64 => for (new_tensor.data.i64[0..total]) |*val| val.* = 1,
            .u64 => for (new_tensor.data.u64[0..total]) |*val| val.* = 1,
        }
        return new_tensor;
    }

    pub fn random_normal(self: *const Tensor, allocator: Allocator, mean: f64, stddev: f64, seed: u64) !Tensor {
        var prng = DefaultPrng.init(seed);
        var random = prng.random();
        var new_tensor = try self.zeros_like(allocator);
        const total = new_tensor.shape.total_elements();
        switch (new_tensor.dtype) {
            .f32 => for (new_tensor.data.f32[0..total]) |*val| {
                val.* = @floatCast(mean + stddev * random.float(f64));
            },
            .f64 => for (new_tensor.data.f64[0..total]) |*val| {
                val.* = mean + stddev * random.float(f64);
            },
            .i32 => for (new_tensor.data.i32[0..total]) |*val| {
                val.* = @intFromFloat(mean + stddev * random.float(f64));
            },
            .u32 => for (new_tensor.data.u32[0..total]) |*val| {
                val.* = @intFromFloat(mean + stddev * random.float(f64));
            },
            .i64 => for (new_tensor.data.i64[0..total]) |*val| {
                val.* = @intFromFloat(mean + stddev * random.float(f64));
            },
            .u64 => for (new_tensor.data.u64[0..total]) |*val| {
                val.* = @intFromFloat(mean + stddev * random.float(f64));
            },
        }
        return new_tensor;
    }

    pub fn clone(self: *const Tensor, allocator: Allocator) !Tensor {
        var new_shape = try self.shape.dupe(allocator);
        var new_tensor = try Tensor.init(allocator, new_shape, self.dtype);
        const total = new_tensor.shape.total_elements();
        switch (self.dtype) {
            .f32 => @memcpy(new_tensor.data.f32, self.data.f32[0..total]),
            .f64 => @memcpy(new_tensor.data.f64, self.data.f64[0..total]),
            .i32 => @memcpy(new_tensor.data.i32, self.data.i32[0..total]),
            .u32 => @memcpy(new_tensor.data.u32, self.data.u32[0..total]),
            .i64 => @memcpy(new_tensor.data.i64, self.data.i64[0..total]),
            .u64 => @memcpy(new_tensor.data.u64, self.data.u64[0..total]),
        }
        new_tensor.offset = self.offset;
        return new_tensor;
    }

    pub fn matmul(self: *const Tensor, other: *const Tensor, allocator: Allocator) !Tensor {
        if (self.shape.dims.len != 2 or other.shape.dims.len != 2) return error.ShapeMismatch;
        if (self.shape.dims[1] != other.shape.dims[0]) return error.MatMulDimensionsMismatch;
        var result_shape = try TensorShape.init(allocator, &.{ self.shape.dims[0], other.shape.dims[1] });
        var result = try Tensor.init(allocator, result_shape, .f64);
        const m = self.shape.dims[0];
        const n = other.shape.dims[1];
        const k = self.shape.dims[1];
        switch (self.dtype) {
            .f64 => {
                const a = self.data.f64;
                const b = other.data.f64;
                const c = result.data.f64;
                for (0..m) |i| {
                    for (0..n) |j| {
                        var sum: f64 = 0.0;
                        for (0..k) |l| {
                            sum += a[i * k + l] * b[l * n + j];
                        }
                        c[i * n + j] = sum;
                    }
                }
            },
            .f32 => {
                const a = self.data.f32;
                const b = other.data.f32;
                const c = result.data.f64;
                for (0..m) |i| {
                    for (0..n) |j| {
                        var sum: f64 = 0.0;
                        for (0..k) |l| {
                            sum += @as(f64, a[i * k + l]) * @as(f64, b[l * n + j]);
                        }
                        c[i * n + j] = sum;
                    }
                }
            },
            else => return error.UnsupportedTypeForMatmul,
        }
        return result;
    }

    pub fn add(self: *const Tensor, other: *const Tensor, allocator: Allocator) !Tensor {
        var broadcast_shape = try self.shape.broadcast(&other.shape);
        var result = try Tensor.init(allocator, broadcast_shape, .f64);
        const total = result.shape.total_elements();
        switch (self.dtype) {
            .f64 => {
                const a = self.data.f64;
                const b = other.data.f64;
                const c = result.data.f64;
                for (0..total) |i| {
                    c[i] = a[i % a.len] + b[i % b.len];
                }
            },
            .f32 => {
                const a = self.data.f32;
                const b = other.data.f32;
                const c = result.data.f64;
                for (0..total) |i| {
                    c[i] = @as(f64, a[i % a.len]) + @as(f64, b[i % b.len]);
                }
            },
            else => return error.UnsupportedTypeForAdd,
        }
        return result;
    }

    pub fn sub(self: *const Tensor, other: *const Tensor, allocator: Allocator) !Tensor {
        var broadcast_shape = try self.shape.broadcast(&other.shape);
        var result = try Tensor.init(allocator, broadcast_shape, .f64);
        const total = result.shape.total_elements();
        switch (self.dtype) {
            .f64 => {
                const a = self.data.f64;
                const b = other.data.f64;
                const c = result.data.f64;
                for (0..total) |i| {
                    c[i] = a[i % a.len] - b[i % b.len];
                }
            },
            .f32 => {
                const a = self.data.f32;
                const b = other.data.f32;
                const c = result.data.f64;
                for (0..total) |i| {
                    c[i] = @as(f64, a[i % a.len]) - @as(f64, b[i % b.len]);
                }
            },
            else => return error.UnsupportedTypeForSub,
        }
        return result;
    }

    pub fn mul(self: *const Tensor, other: *const Tensor, allocator: Allocator) !Tensor {
        var broadcast_shape = try self.shape.broadcast(&other.shape);
        var result = try Tensor.init(allocator, broadcast_shape, .f64);
        const total = result.shape.total_elements();
        switch (self.dtype) {
            .f64 => {
                const a = self.data.f64;
                const b = other.data.f64;
                const c = result.data.f64;
                for (0..total) |i| {
                    c[i] = a[i % a.len] * b[i % b.len];
                }
            },
            .f32 => {
                const a = self.data.f32;
                const b = other.data.f32;
                const c = result.data.f64;
                for (0..total) |i| {
                    c[i] = @as(f64, a[i % a.len]) * @as(f64, b[i % b.len]);
                }
            },
            else => return error.UnsupportedTypeForMul,
        }
        return result;
    }

    pub fn transpose(self: *const Tensor, allocator: Allocator) !Tensor {
        if (self.shape.dims.len != 2) return error.NotMatrix;
        var result_shape = try TensorShape.init(allocator, &.{ self.shape.dims[1], self.shape.dims[0] });
        var result = try Tensor.init(allocator, result_shape, self.dtype);
        const m = self.shape.dims[0];
        const n = self.shape.dims[1];
        switch (self.dtype) {
            .f64 => {
                const a = self.data.f64;
                const c = result.data.f64;
                for (0..m) |i| {
                    for (0..n) |j| {
                        c[j * m + i] = a[i * n + j];
                    }
                }
            },
            .f32 => {
                const a = self.data.f32;
                const c = result.data.f32;
                for (0..m) |i| {
                    for (0..n) |j| {
                        c[j * m + i] = a[i * n + j];
                    }
                }
            },
            else => return error.UnsupportedTypeForTranspose,
        }
        return result;
    }

    pub fn sum(self: *const Tensor, axis: ?usize, allocator: Allocator) !Tensor {
        if (axis) |ax| if (ax >= self.shape.dims.len) return error.InvalidAxis;
        var result_shape = try self.shape.dupe(allocator);
        var result_total: usize = 1;
        if (axis) |ax| {
            result_shape.dims[ax] = 1;
            for (result_shape.dims) |dim| result_total *= dim;
        } else {
            result_total = 1;
        }
        var result = try Tensor.init(allocator, result_shape, .f64);
        switch (self.dtype) {
            .f64 => {
                const a = self.data.f64;
                const c = result.data.f64;
                if (axis == null) {
                    var sum: f64 = 0.0;
                    for (a) |val| sum += val;
                    for (c) |*val| val.* = sum;
                } else {
                    const ax = axis.?;
                    const stride = self.strides[ax];
                    for (0..result_total) |i| {
                        var sum: f64 = 0.0;
                        var offset = i * stride;
                        for (0..self.shape.dims[ax]) |k| {
                            sum += a[offset + k * stride];
                        }
                        c[i] = sum;
                    }
                }
            },
            .f32 => {
                const a = self.data.f32;
                const c = result.data.f64;
                if (axis == null) {
                    var sum: f64 = 0.0;
                    for (a) |val| sum += @as(f64, val);
                    for (c) |*val| val.* = sum;
                } else {
                    const ax = axis.?;
                    const stride = self.strides[ax];
                    for (0..result_total) |i| {
                        var sum: f64 = 0.0;
                        var offset = i * stride;
                        for (0..self.shape.dims[ax]) |k| {
                            sum += @as(f64, a[offset + k * stride]);
                        }
                        c[i] = sum;
                    }
                }
            },
            else => return error.UnsupportedTypeForSum,
        }
        return result;
    }

    pub fn mean(self: *const Tensor, axis: ?usize, allocator: Allocator) !Tensor {
        var sum_tensor = try self.sum(axis, allocator);
        defer sum_tensor.deinit();
        const count = if (axis) |ax| self.shape.dims[ax] else self.shape.total_elements();
        if (count == 0) return error.ZeroDivision;
        var scale_tensor = try Tensor.init(allocator, sum_tensor.shape, .f64);
        defer scale_tensor.deinit();
        const scale = 1.0 / @as(f64, @floatFromInt(count));
        for (scale_tensor.data.f64) |*val| val.* = scale;
        var result = try sum_tensor.mul(&scale_tensor, allocator);
        return result;
    }

    pub fn argmax(self: *const Tensor, axis: usize, allocator: Allocator) !Tensor {
        if (axis >= self.shape.dims.len) return error.InvalidAxis;
        var result_shape = try self.shape.dupe(allocator);
        result_shape.dims[axis] = 1;
        var result = try Tensor.init(allocator, result_shape, .u32);
        const total = self.shape.total_elements();
        const stride = self.strides[axis];
        switch (self.dtype) {
            .f64 => {
                const a = self.data.f64;
                const c = result.data.u32;
                for (0..result.shape.total_elements()) |i| {
                    var max_val: f64 = -math.inf(f64);
                    var max_idx: u32 = 0;
                    var offset = i * stride;
                    for (0..self.shape.dims[axis]) |k| {
                        const val = a[offset + @as(usize, @intCast(k)) * stride];
                        if (val > max_val) {
                            max_val = val;
                            max_idx = @as(u32, @intCast(k));
                        }
                    }
                    c[i] = max_idx;
                }
            },
            .f32 => {
                const a = self.data.f32;
                const c = result.data.u32;
                for (0..result.shape.total_elements()) |i| {
                    var max_val: f32 = -math.inf(f32);
                    var max_idx: u32 = 0;
                    var offset = i * stride;
                    for (0..self.shape.dims[axis]) |k| {
                        const val = a[offset + @as(usize, @intCast(k)) * stride];
                        if (val > max_val) {
                            max_val = val;
                            max_idx = @as(u32, @intCast(k));
                        }
                    }
                    c[i] = max_idx;
                }
            },
            else => return error.UnsupportedTypeForArgmax,
        }
        return result;
    }

    pub fn softmax(self: *const Tensor, allocator: Allocator) !Tensor {
        var result = try self.clone(allocator);
        const total = result.shape.total_elements();
        switch (result.dtype) {
            .f64 => {
                const data = result.data.f64;
                var max_val: f64 = -math.inf(f64);
                for (data[0..total]) |val| if (val > max_val) max_val = val;
                var sum_exp: f64 = 0.0;
                for (data[0..total]) |val| sum_exp += math.exp(val - max_val);
                for (data[0..total]) |*val| val.* = math.exp(val.* - max_val) / sum_exp;
            },
            .f32 => {
                const data = result.data.f32;
                var max_val: f32 = -math.inf(f32);
                for (data[0..total]) |val| if (val > max_val) max_val = val;
                var sum_exp: f32 = 0.0;
                for (data[0..total]) |val| sum_exp += @floatCast(math.exp(@as(f64, val) - @as(f64, max_val)));
                for (data[0..total]) |*val| val.* = @floatCast(math.exp(@as(f64, val.*) - @as(f64, max_val)) / @as(f64, sum_exp));
            },
            else => return error.UnsupportedTypeForSoftmax,
        }
        return result;
