    pub fn view(self: *const Tensor, new_shape: []const usize, allocator: Allocator) !Tensor {
        var view_shape = try TensorShape.init(allocator, new_shape);
        if (view_shape.total_elements() != self.shape.total_elements()) return error.ViewSizeMismatch;
        return Tensor{
            .shape = view_shape,
            .data = self.data,
            .allocator = allocator,
            .dtype = self.dtype,
            .strides = try self.strides.dupe(allocator),
            .offset = self.offset,
        };
    }

    pub fn flatten(self: *const Tensor, allocator: Allocator) !Tensor {
        return try self.view(&.{self.shape.total_elements()}, allocator);
    }

    pub fn reshape(self: *const Tensor, new_dims: []const usize, allocator: Allocator) !Tensor {
        var new_shape = try TensorShape.init(allocator, new_dims);
        if (new_shape.total_elements() != self.shape.total_elements()) return error.ReshapeSizeMismatch;
        var result = try self.clone(allocator);
        result.shape.deinit();
        result.shape = new_shape;
        result.strides.deinit();
        result.strides = try allocator.alloc(usize, new_shape.dims.len);
        var stride: usize = 1;
        for (new_shape.dims.len - 1..0) |i| {
            result.strides[i] = stride;
            stride *= new_shape.dims[i + 1];
        }
        if (new_shape.dims.len > 0) {
            result.strides[0] = stride;
        }
        return result;
    }

    pub fn at(self: *const Tensor, indices: []usize) !f64 {
        if (indices.len != self.shape.dims.len) return error.IndexDimensionMismatch;
        var idx: usize = self.offset;
        for (indices, self.strides) |i, s| {
            if (i >= self.shape.dims[@intFromPtr(&s - self.strides.ptr)]) return error.IndexOutOfBounds;
            idx += i * s;
        }
        return self.data.get_scalar(idx) orelse error.IndexOutOfBounds;
    }

    pub fn set(self: *Tensor, indices: []usize, value: f64) !void {
        if (indices.len != self.shape.dims.len) return error.IndexDimensionMismatch;
        var idx: usize = self.offset;
        for (indices, self.strides) |i, s| {
            if (i >= self.shape.dims[@intFromPtr(&s - self.strides.ptr)]) return error.IndexOutOfBounds;
            idx += i * s;
        }
        try self.data.set_scalar(idx, value);
    }

    pub fn apply(self: *Tensor, func: fn (f64) f64) !void {
        const total = self.shape.total_elements();
        switch (self.dtype) {
            .f64 => for (self.data.f64[0..total]) |*val| val.* = func(val.*),
            .f32 => for (self.data.f32[0..total]) |*val| val.* = @floatCast(func(@as(f64, val.*))),
            else => return error.UnsupportedTypeForApply,
        }
    }

    pub fn reduce(self: *const Tensor, func: fn (f64, f64) f64, initial: f64, allocator: Allocator) !f64 {
        const total = self.shape.total_elements();
        var result: f64 = initial;
        switch (self.dtype) {
            .f64 => for (self.data.f64[0..total]) |val| result = func(result, val),
            .f32 => for (self.data.f32[0..total]) |val| result = func(result, @as(f64, val)),
            else => return error.UnsupportedTypeForReduce,
        }
        return result;
    }

    pub fn concatenate(self: *const Tensor, other: *const Tensor, allocator: Allocator, axis: usize) !Tensor {
        if (self.shape.dims.len != other.shape.dims.len) return error.ConcatDimensionMismatch;
        if (self.shape.dims[axis] + other.shape.dims[axis] > std.math.maxInt(usize)) return error.ConcatOverflow;
        var result_shape = try self.shape.dupe(allocator);
        result_shape.dims[axis] += other.shape.dims[axis];
        var result = try Tensor.init(allocator, result_shape, self.dtype);
        const self_stride = self.strides[axis];
        const other_stride = other.strides[axis];
        const total = result.shape.total_elements();
        const result_stride = result.strides[axis];
        switch (self.dtype) {
            .f64 => {
                const a = self.data.f64;
                const b = other.data.f64;
                const c = result.data.f64;
                var offset: usize = 0;
                for (0..total / 2) |i| {
                    const self_idx = i * self_stride;
                    const other_idx = i * other_stride;
                    const result_idx = offset + i * result_stride;
                    c[result_idx] = a[self_idx];
                }
                offset += self.shape.dims[axis] * result_stride;
                for (0..total / 2) |i| {
                    const other_idx = i * other_stride;
                    const result_idx = offset + i * result_stride;
                    c[result_idx] = b[other_idx];
                }
            },
            else => return error.UnsupportedTypeForConcat,
        }
        return result;
    }
};

