    }

    pub fn mul(self: *const Tensor, other: *const Tensor, allocator: Allocator) !Tensor {
        var broadcast_shape = try self.shape.broadcast(&other.shape);
        var result = try Tensor.init(allocator, broadcast_shape, .f64);
        const total = result.shape.total_elements();
        switch (self.dtype) {
            .f64 => {
                const a = self.data.f64;
                const b = other.data.f64;
                const c = result.data.f64;
                for (0..total) |i| {
                    c[i] = a[i % a.len] * b[i % b.len];
                }
            },
            .f32 => {
                const a = self.data.f32;
                const b = other.data.f32;
                const c = result.data.f64;
                for (0..total) |i| {
                    c[i] = @as(f64, a[i % a.len]) * @as(f64, b[i % b.len]);
                }
            },
            else => return error.UnsupportedTypeForMul,
        }
        return result;
    }

    pub fn transpose(self: *const Tensor, allocator: Allocator) !Tensor {
        if (self.shape.dims.len != 2) return error.NotMatrix;
        var result_shape = try TensorShape.init(allocator, &.{ self.shape.dims[1], self.shape.dims[0] });
        var result = try Tensor.init(allocator, result_shape, self.dtype);
        const m = self.shape.dims[0];
        const n = self.shape.dims[1];
        switch (self.dtype) {
            .f64 => {
                const a = self.data.f64;
                const c = result.data.f64;
                for (0..m) |i| {
                    for (0..n) |j| {
                        c[j * m + i] = a[i * n + j];
                    }
                }
            },
            .f32 => {
                const a = self.data.f32;
                const c = result.data.f32;
                for (0..m) |i| {
                    for (0..n) |j| {
                        c[j * m + i] = a[i * n + j];
                    }
                }
            },
            else => return error.UnsupportedTypeForTranspose,
        }
        return result;
    }

    pub fn sum(self: *const Tensor, axis: ?usize, allocator: Allocator) !Tensor {
        if (axis) |ax| if (ax >= self.shape.dims.len) return error.InvalidAxis;
        var result_shape = try self.shape.dupe(allocator);
        var result_total: usize = 1;
        if (axis) |ax| {
            result_shape.dims[ax] = 1;
            for (result_shape.dims) |dim| result_total *= dim;
        } else {
            result_total = 1;
        }
        var result = try Tensor.init(allocator, result_shape, .f64);
        switch (self.dtype) {
            .f64 => {
                const a = self.data.f64;
                const c = result.data.f64;
                if (axis == null) {
                    var sum: f64 = 0.0;
                    for (a) |val| sum += val;
                    for (c) |*val| val.* = sum;
                } else {
                    const ax = axis.?;
                    const stride = self.strides[ax];
                    for (0..result_total) |i| {
                        var sum: f64 = 0.0;
                        var offset = i * stride;
                        for (0..self.shape.dims[ax]) |k| {
                            sum += a[offset + k * stride];
                        }
                        c[i] = sum;
                    }
                }
            },
            .f32 => {
                const a = self.data.f32;
                const c = result.data.f64;
                if (axis == null) {
                    var sum: f64 = 0.0;
                    for (a) |val| sum += @as(f64, val);
                    for (c) |*val| val.* = sum;
                } else {
                    const ax = axis.?;
                    const stride = self.strides[ax];
                    for (0..result_total) |i| {
                        var sum: f64 = 0.0;
                        var offset = i * stride;
                        for (0..self.shape.dims[ax]) |k| {
                            sum += @as(f64, a[offset + k * stride]);
                        }
                        c[i] = sum;
                    }
                }
            },
            else => return error.UnsupportedTypeForSum,
        }
        return result;
    }

    pub fn mean(self: *const Tensor, axis: ?usize, allocator: Allocator) !Tensor {
        var sum_tensor = try self.sum(axis, allocator);
        defer sum_tensor.deinit();
        const count = if (axis) |ax| self.shape.dims[ax] else self.shape.total_elements();
        if (count == 0) return error.ZeroDivision;
        var scale_tensor = try Tensor.init(allocator, sum_tensor.shape, .f64);
        defer scale_tensor.deinit();
        const scale = 1.0 / @as(f64, @floatFromInt(count));
        for (scale_tensor.data.f64) |*val| val.* = scale;
        var result = try sum_tensor.mul(&scale_tensor, allocator);
        return result;
    }

    pub fn argmax(self: *const Tensor, axis: usize, allocator: Allocator) !Tensor {
        if (axis >= self.shape.dims.len) return error.InvalidAxis;
        var result_shape = try self.shape.dupe(allocator);
        result_shape.dims[axis] = 1;
        var result = try Tensor.init(allocator, result_shape, .u32);
        const total = self.shape.total_elements();
        const stride = self.strides[axis];
        switch (self.dtype) {
            .f64 => {
                const a = self.data.f64;
                const c = result.data.u32;
                for (0..result.shape.total_elements()) |i| {
                    var max_val: f64 = -math.inf(f64);
                    var max_idx: u32 = 0;
                    var offset = i * stride;
                    for (0..self.shape.dims[axis]) |k| {
                        const val = a[offset + @as(usize, @intCast(k)) * stride];
                        if (val > max_val) {
                            max_val = val;
                            max_idx = @as(u32, @intCast(k));
                        }
                    }
                    c[i] = max_idx;
                }
            },
            .f32 => {
                const a = self.data.f32;
                const c = result.data.u32;
                for (0..result.shape.total_elements()) |i| {
                    var max_val: f32 = -math.inf(f32);
                    var max_idx: u32 = 0;
                    var offset = i * stride;
                    for (0..self.shape.dims[axis]) |k| {
                        const val = a[offset + @as(usize, @intCast(k)) * stride];
                        if (val > max_val) {
                            max_val = val;
                            max_idx = @as(u32, @intCast(k));
                        }
                    }
                    c[i] = max_idx;
                }
            },
            else => return error.UnsupportedTypeForArgmax,
        }
        return result;
    }

    pub fn softmax(self: *const Tensor, allocator: Allocator) !Tensor {
        var result = try self.clone(allocator);
        const total = result.shape.total_elements();
        switch (result.dtype) {
            .f64 => {
                const data = result.data.f64;
                var max_val: f64 = -math.inf(f64);
                for (data[0..total]) |val| if (val > max_val) max_val = val;
                var sum_exp: f64 = 0.0;
                for (data[0..total]) |val| sum_exp += math.exp(val - max_val);
                for (data[0..total]) |*val| val.* = math.exp(val.* - max_val) / sum_exp;
            },
            .f32 => {
                const data = result.data.f32;
                var max_val: f32 = -math.inf(f32);
                for (data[0..total]) |val| if (val > max_val) max_val = val;
                var sum_exp: f32 = 0.0;
                for (data[0..total]) |val| sum_exp += @floatCast(math.exp(@as(f64, val) - @as(f64, max_val)));
                for (data[0..total]) |*val| val.* = @floatCast(math.exp(@as(f64, val.*) - @as(f64, max_val)) / @as(f64, sum_exp));
            },
            else => return error.UnsupportedTypeForSoftmax,
        }
        return result;
    }

    pub fn view(self: *const Tensor, new_shape: []const usize, allocator: Allocator) !Tensor {
        var view_shape = try TensorShape.init(allocator, new_shape);
        if (view_shape.total_elements() != self.shape.total_elements()) return error.ViewSizeMismatch;
        return Tensor{
            .shape = view_shape,
            .data = self.data,
            .allocator = allocator,
            .dtype = self.dtype,
            .strides = try self.strides.dupe(allocator),
            .offset = self.offset,
        };
    }

    pub fn flatten(self: *const Tensor, allocator: Allocator) !Tensor {
        return try self.view(&.{self.shape.total_elements()}, allocator);
    }

    pub fn reshape(self: *const Tensor, new_dims: []const usize, allocator: Allocator) !Tensor {
        var new_shape = try TensorShape.init(allocator, new_dims);
        if (new_shape.total_elements() != self.shape.total_elements()) return error.ReshapeSizeMismatch;
        var result = try self.clone(allocator);
        result.shape.deinit();
        result.shape = new_shape;
        result.strides.deinit();
        result.strides = try allocator.alloc(usize, new_shape.dims.len);
        var stride: usize = 1;
        for (new_shape.dims.len - 1..0) |i| {
            result.strides[i] = stride;
            stride *= new_shape.dims[i + 1];
        }
        if (new_shape.dims.len > 0) {
            result.strides[0] = stride;
        }
        return result;
    }

    pub fn at(self: *const Tensor, indices: []usize) !f64 {
        if (indices.len != self.shape.dims.len) return error.IndexDimensionMismatch;
        var idx: usize = self.offset;
        for (indices, self.strides) |i, s| {
            if (i >= self.shape.dims[@intFromPtr(&s - self.strides.ptr)]) return error.IndexOutOfBounds;
            idx += i * s;
        }
        return self.data.get_scalar(idx) orelse error.IndexOutOfBounds;
    }

    pub fn set(self: *Tensor, indices: []usize, value: f64) !void {
        if (indices.len != self.shape.dims.len) return error.IndexDimensionMismatch;
        var idx: usize = self.offset;
        for (indices, self.strides) |i, s| {
            if (i >= self.shape.dims[@intFromPtr(&s - self.strides.ptr)]) return error.IndexOutOfBounds;
            idx += i * s;
        }
        try self.data.set_scalar(idx, value);
    }

    pub fn apply(self: *Tensor, func: fn (f64) f64) !void {
        const total = self.shape.total_elements();
        switch (self.dtype) {
            .f64 => for (self.data.f64[0..total]) |*val| val.* = func(val.*),
            .f32 => for (self.data.f32[0..total]) |*val| val.* = @floatCast(func(@as(f64, val.*))),
            else => return error.UnsupportedTypeForApply,
        }
    }

    pub fn reduce(self: *const Tensor, func: fn (f64, f64) f64, initial: f64, allocator: Allocator) !f64 {
        const total = self.shape.total_elements();
        var result: f64 = initial;
        switch (self.dtype) {
            .f64 => for (self.data.f64[0..total]) |val| result = func(result, val),
            .f32 => for (self.data.f32[0..total]) |val| result = func(result, @as(f64, val)),
            else => return error.UnsupportedTypeForReduce,
        }
        return result;
    }

    pub fn concatenate(self: *const Tensor, other: *const Tensor, allocator: Allocator, axis: usize) !Tensor {
        if (self.shape.dims.len != other.shape.dims.len) return error.ConcatDimensionMismatch;
        if (self.shape.dims[axis] + other.shape.dims[axis] > std.math.maxInt(usize)) return error.ConcatOverflow;
        var result_shape = try self.shape.dupe(allocator);
        result_shape.dims[axis] += other.shape.dims[axis];
        var result = try Tensor.init(allocator, result_shape, self.dtype);
        const self_stride = self.strides[axis];
        const other_stride = other.strides[axis];
        const total = result.shape.total_elements();
        const result_stride = result.strides[axis];
        switch (self.dtype) {
            .f64 => {
                const a = self.data.f64;
                const b = other.data.f64;
                const c = result.data.f64;
                var offset: usize = 0;
                for (0..total / 2) |i| {
                    const self_idx = i * self_stride;
                    const other_idx = i * other_stride;
                    const result_idx = offset + i * result_stride;
                    c[result_idx] = a[self_idx];
                }
                offset += self.shape.dims[axis] * result_stride;
                for (0..total / 2) |i| {
                    const other_idx = i * other_stride;
                    const result_idx = offset + i * result_stride;
                    c[result_idx] = b[other_idx];
                }
            },
            else => return error.UnsupportedTypeForConcat,
        }
        return result;
    }
};
